"""Regenerate docs/snippets/version.md from pyproject.toml.

Every version bump must ship with up-to-date docs: run this script
after `poetry version ...` and commit the result. CI regenerates the
snippet and fails on any git diff, so a bumped version can never merge
with a stale stamp on the docs landing page.
"""

import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PYPROJECT = ROOT / "pyproject.toml"
SNIPPET = ROOT / "docs" / "snippets" / "version.md"
REPO_SLUG = "nyjc-computing/flask-campus"

TEMPLATE = """\
<!-- AUTO-GENERATED by scripts/sync_docs_version.py — do not edit.
     Run `python scripts/sync_docs_version.py` after a version bump;
     CI regenerates this file and fails on drift. -->

**Current release: [v{version}](https://github.com/{slug}/releases/tag/v{version})**
· release notes in the [changelog](https://github.com/{slug}/blob/main/CHANGELOG.md)
and on the [releases page](https://github.com/{slug}/releases).
"""


def main() -> None:
    data = tomllib.loads(PYPROJECT.read_text(encoding="utf-8"))
    version = data["tool"]["poetry"]["version"]
    SNIPPET.parent.mkdir(parents=True, exist_ok=True)
    SNIPPET.write_text(
        TEMPLATE.format(version=version, slug=REPO_SLUG),
        encoding="utf-8",
    )
    print(f"docs/snippets/version.md -> v{version}")


if __name__ == "__main__":
    main()
